class Text {
    static String change(String s) {
        s += "X";
        return s.substring(1);
    }
    static void change(StringBuilder b) {
        b.append("Y");
        b.deleteCharAt(0);
    }
}
public class Main {
    public static void main(String[] args) {
        String s = "ABC";
        String r = Text.change(s);
        StringBuilder b = new StringBuilder(s);
        Text.change(b);
        System.out.print(s + ":" + r + ":" + b);
    }
}

