class Joiner {
    static String join(String left, String right) {
        left.concat(right);
        return left;
    }
    static StringBuilder join(StringBuilder left, String right) {
        return left.append(right);
    }
}
public class Main {
    public static void main(String[] args) {
        String x = "A";
        StringBuilder y = new StringBuilder("B");
        String p = Joiner.join(x, "1");
        StringBuilder q = Joiner.join(y, "2");
        System.out.print(x + ":" + p + ":" + y + ":" + (y == q));
    }
}

class Show {
