public class Main {
    static String label(String s) {
        return switch (s.length()) {
            case 0 -> "E";
            case 1, 2 -> s.toUpperCase();
            default -> {
                String t = s.substring(0, 2);
                yield t + s.charAt(s.length() - 1);
            }
        };
    }
    public static void main(String[] args) {
        System.out.print(label("") + ":");
        System.out.print(label("ab") + ":");
        System.out.print(label("java"));
    }
}

public class Main {
    static void step(StringBuilder a, StringBuilder b) {
        a.append("1");
        b.append("2");
        a = b;
        a.append("3");
    }
    public static void main(String[] args) {
        var x = new StringBuilder("X");
        var y = new StringBuilder("Y");
        step(x, y);
        System.out.print(x + ":" + y);
    }
}

public class Main {
    static String trimHead(String s) {
        if (s == null || s.length() < 2) {
            return s;
        }
        return s.substring(1);
    }
    public static void main(String[] args) {
        String a = null;
        String b = "Z";
        String c = "Java";
        System.out.print(trimHead(a) + ":");
        System.out.print(trimHead(b) + ":");
        System.out.print(trimHead(c));
    }
}

